// "Peixe-papagaio – parte 2/3": the timeline. Every scene lasts exactly its narration file
// (+4 frames); every cue below is taken from a spoken word (src/papagaio2/words.ts, generated by
// scripts/papagaio2_words.py from the audio). Everything else (3D, overlays, sfx) reads from here.
import { NARRATION } from "./words";

export const FPS = 30;
export const TAIL_FRAMES = 4;

export const SCENE_DURATIONS = NARRATION.map((n) => Math.ceil(n.dur * FPS) + TAIL_FRAMES);
export const S = SCENE_DURATIONS.map((_, i) => SCENE_DURATIONS.slice(0, i).reduce((a, b) => a + b, 0));
export const DURATION = SCENE_DURATIONS.reduce((a, b) => a + b, 0);
export const sceneEnd = (i: number) => S[i] + SCENE_DURATIONS[i];
export const at = (i: number, sec: number) => S[i] + Math.round(sec * FPS);
export const sceneOf = (f: number) => {
  for (let i = S.length - 1; i >= 0; i--) if (f >= S[i]) return i;
  return 0;
};
/** start (absolute frame) of the n-th caption word of scene i (0-based) */
export const word = (i: number, n: number) => at(i, NARRATION[i].t[n]);

// ---------------------------------------------------------------------------
// Cues (absolute frames)
// ---------------------------------------------------------------------------
// scene 1: recap by day, then the vote result at night
export const C1_ISLAND = word(0, 7) - 3; // "faz ilhas": the islet from above
export const C1_SAND = word(0, 12) - 3; // "cocô": close on the grains of sand
export const C1_NIGHT = word(0, 13) - 3; // "E você escolheu": quick cut to the night
export const C1_BUBBLES = C1_NIGHT + 4; // the comment bubbles rise (one every BUBBLE_GAP frames)
export const BUBBLE_GAP = 3;
export const BUBBLE_COUNT = 9;
export const C1_RESULT = word(0, 16) - 2; // "dormir no saco de baba": VOCÊ ESCOLHEU: A
// scene 2: the slime sleeping bag
export const C2_SOLTA = word(1, 4) - 2; // "você solta um muco": close on the mouth
export const C2_COVER = word(1, 11) - 2; // "que vai cobrindo": it spreads over the body
export const C2_HOUR = word(1, 16) - 2; // "Em menos de uma hora": the clock
export const C2_CLOSED = word(1, 26); // "bolha": the cocoon is closed
export const C2_PUSH = word(1, 27) - 2; // "Esse é o seu": push in
export const C2_LABEL = word(1, 31); // "mosquiteiro"
// scene 3: the parasites cannot get in
export const C3_SIDE = word(2, 3) - 2; // "famintos por sangue"
export const C3_HIT = word(2, 6) - 2; // "Mas não conseguem passar": close-up of the bounces
export const HITS = [4, 11, 18, 25, 32, 39].map((k) => C3_HIT + k).filter((f) => f < S[3] - 4);
// scene 4: the experiment (split screen), then the battery
export const C4_95 = word(3, 3); // "noventa e cinco por cento"
export const COUNT95_FRAMES = word(3, 4) - word(3, 3) - 2;
export const C4_ANGLE = word(3, 11) - 2; // "Com a bolha": second angle on both halves
export const C4_10 = word(3, 15); // "dez por cento"
export const COUNT10_FRAMES = 18;
export const C4_BACK = word(3, 16) - 2; // "E fazer essa bolha custa": back to the sleeping fish
export const C4_BATTERY = word(3, 20) - 4; // "custa": the battery shows up
export const C4_25 = word(3, 22); // "dois e meio por cento": a sliver drains
// scene 5: you were right
export const C5_CHECK = word(4, 1); // "acertou"
export const C5_OUT = word(4, 3) - 2; // "sobreviveu à noite": dawn, the fish pushes out
// scene 6: dawn, hungry
export const C6_LEAVE = word(5, 1) - 2; // "Você sai da bolha"
export const C6_CLOSE = word(5, 5) - 2; // "e está com fome": close-up
export const C6_GROWL = word(5, 8); // "fome": the belly rumbles
// scene 7: the choice
export const C7_A = word(6, 4); // "A:"
export const C7_B = word(6, 14); // "B:"
// scene 8: careful
export const C8_PUSH = word(7, 4); // "Mas cuidado": slow push-in on the cards
export const C8_NADA = word(7, 10); // "sem nada": quick shake + darker background
export const C8_Q = word(7, 6); // "uma delas te deixa sem nada para comer": the red question mark
// scene 9: tag a friend (inside the reef: small cards in the back, a confused friend fish, a comment box)
export const C9_TEXT = S[8] + 2; // MARCA AQUELE AMIGO (small title on top) + the cards step back
export const C9_BOX = S[8] + 6; // the comment box pops up above the caption
export const C9_TYPE = word(8, 3); // "amigo": "@" is typed
// the friend swims from card A towards B, turns, back towards A, turns again: it never picks one
export const C9_TURNS = [S[8] + 22, S[8] + 48];

// series badge: only the first 3 s and scenes 7-9 (the cards)
export const BADGE: [number, number][] = [
  [0, 3 * FPS],
  [S[6], DURATION],
];

// scene 8: from "uma delas te deixa sem nada para comer", cards A and B pulse in turn, one tension beat each
export const PULSE_GAP = 12;
export const PULSE_LEN = 10;
export const C8_PULSES = Array.from({ length: 12 }, (_, i) => C8_Q + i * PULSE_GAP).filter((f) => f + PULSE_LEN <= S[8]);

// Whip (lateral blur + whoosh) ONLY on the real changes of scene, never in the middle of a sentence
// (max 4 per video, CLAUDE.md): recap -> night, parasites -> experiment, -> the A/B cards.
// Every other change of framing is a hard cut or a smooth camera move: no blur, no whoosh.
export const WHIPS = [C1_NIGHT, S[3], S[6]];
// night -> dawn: a soft flash with a soft sound, no whoosh
export const C_DAWN = S[5];
